package com.example.blades360;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.Bundle;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public final class StreamingInstrumentation extends Instrumentation {
 int checks;MainActivity a;JellyfinBrowser browser;IptvBrowser iptv;
 void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
 void ui(Runnable r){runOnMainSync(r);}
 Object request(JellyfinClient client,String path)throws Exception{if(client instanceof PlexClient){Object result=((PlexClient)client).read(path,client.server());check(result!=null,"Plex response decoded");return result;}Object[] value={null};CountDownLatch done=new CountDownLatch(1);ui(()->client.get(path,v->{value[0]=v;done.countDown();}));check(done.await(25,TimeUnit.SECONDS),client.name()+" request completes at check "+checks+" ("+client.status+")");return value[0];}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle output=new Bundle();a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));String session="blades360-iptv-test";
  try{ui(()->{if(a.bootAnimation!=null)a.bootAnimation.finish();a.openJellyfin();browser=a.jellyfinBrowser;});check(browser.screen==8&&browser.rows.size()==4,"Media Center service chooser");
   String m3u="\ufeff#EXTM3U x-tvg-url=\"guide.xml\"\n#EXTINF:-1 tvg-id=\"alpha\" group-title=\"News, Local\" tvg-logo=\"logo.png\" catchup-source=\"archive/{utc}/{duration}.m3u8\" catchup-days=\"3\",Test, One\n#EXTVLCOPT:http-user-agent=BladesFixture\nlive.m3u8\n#EXTINF:-1,Duplicate\nlive.m3u8\n#EXTINF:-1 tvg-id=\"beta\",Second\nhttps://example.invalid/two.ts|Referer=https%3A%2F%2Fexample.invalid\n";
   IptvData.Playlist parsed=IptvData.playlist(m3u,"https://example.invalid/list.m3u");check(parsed.channels.size()==2,"Duplicate streams removed");IptvData.Channel c=parsed.channels.get(0);check(c.name.equals("Test, One")&&c.group.equals("News, Local"),"Quoted comma attributes and names parsed");check(c.url.equals("https://example.invalid/live.m3u8"),"Relative URLs resolved");check(c.headers.get("User-Agent").equals("BladesFixture"),"Per-channel user agent");check(parsed.guide.equals("https://example.invalid/guide.xml"),"Guide discovery");check(IptvData.resolve("https://example.invalid/list.m3u","").isEmpty(),"Missing logo does not resolve to playlist");check(IptvData.playlist("#EXTM3U\n#EXT-X-TARGETDURATION:6\n#EXTINF:6,\na.ts", "https://example.invalid/live.m3u8").channels.size()==1,"HLS media playlist is one channel");
   check(IptvData.date("20261114080000 -0500")==IptvData.date("20261114130000 +0000"),"XMLTV timezone offsets");long now=System.currentTimeMillis();java.text.SimpleDateFormat date=new java.text.SimpleDateFormat("yyyyMMddHHmmss Z",Locale.ROOT);date.setTimeZone(TimeZone.getTimeZone("UTC"));String xml="<?xml version=\"1.0\"?><tv><programme channel=\"alpha\" start=\""+date.format(new Date(now-60000))+"\" stop=\""+date.format(new Date(now+60000))+"\"><title>Now &amp; Next</title><desc>Fixture guide</desc></programme></tv>";ArrayList<IptvData.Programme> guide=IptvData.guide(new ByteArrayInputStream(xml.getBytes("UTF-8")),Collections.singleton("alpha"),now);check(guide.size()==1&&guide.get(0).title.equals("Now & Next"),"XMLTV programme parsing");IptvData.Programme past=new IptvData.Programme();past.start=now-3600000;past.end=now-1800000;check(IptvData.catchup(c,past,now).contains("1800"),"Provider catch-up template");check(IptvData.catchup(c,guide.get(0),now).isEmpty(),"Current programmes do not use catch-up");
   PrivateMediaFile.write(a,"iptv-test.bin","fixture-secret");check(PrivateMediaFile.read(a,"iptv-test.bin").equals("fixture-secret"),"Encrypted file round trip");try(FileInputStream in=a.openFileInput("iptv-test.bin")){byte[] bytes=new byte[in.available()];in.read(bytes);check(!new String(bytes,"ISO-8859-1").contains("fixture-secret"),"Cached source is encrypted");}a.deleteFile("iptv-test.bin");
   check(a.plex.connected(),"Plex token configured");JSONArray users=(JSONArray)request(a.plex,"/Users");check(users.length()==1,"Plex server identity");JSONObject libs=(JSONObject)request(a.plex,"/Users/server/Views");check(libs.getJSONArray("Items").length()>=2,"Plex libraries");String parent=libs.getJSONArray("Items").getJSONObject(0).getString("Id");JSONObject first=(JSONObject)request(a.plex,"/Items?ParentId="+parent+"&Limit=2&StartIndex=0");JSONObject second=(JSONObject)request(a.plex,"/Items?ParentId="+parent+"&Limit=2&StartIndex=2");check(!first.getJSONArray("Items").getJSONObject(0).getString("Id").equals(second.getJSONArray("Items").getJSONObject(0).getString("Id")),"Plex pagination");JSONObject movie=first.getJSONArray("Items").getJSONObject(0);
   ui(()->{browser.service(a.plex);browser.selected=movie;browser.page(3);browser.play();});boolean[] ready={false};for(int i=0;i<50;i++){ui(()->ready[0]=browser.player!=null&&browser.player.prepared);if(ready[0])break;Thread.sleep(500);}check(ready[0],"Plex live playback prepares");ui(()->{browser.player.pause();browser.player.close();browser.close();a.openIptv();iptv=a.iptvBrowser;});
   JSONObject media=(JSONObject)request(a.jellyfin,"/Items?UserId="+a.jellyfin.user()+"&Recursive=true&IncludeItemTypes=Movie&Limit=1&Fields=MediaSources");JSONObject sample=media.getJSONArray("Items").getJSONObject(0);String id=sample.getString("Id");String source=sample.getJSONArray("MediaSources").getJSONObject(0).getString("Id");IptvData.Channel test=new IptvData.Channel();test.id="test-only-channel";test.name="IPTV player test";test.group="Test fixture";test.url=a.jellyfin.server()+"/Videos/"+id+"/master.m3u8?MediaSourceId="+source+"&VideoCodec=h264&AudioCodec=aac&VideoBitrate=4000000&AudioBitrate=192000&MaxWidth=1280&TranscodingMaxAudioChannels=2&SegmentContainer=ts&MinSegments=2&DeviceId=blades360-tablet&PlaySessionId="+session;test.headers=a.jellyfin.headers();
   ui(()->{iptv.player=new IptvPlayer(iptv,test,null);a.addContentView(iptv.player,new android.view.ViewGroup.LayoutParams(-1,-1));iptv.player.requestFocus();});ready[0]=false;for(int i=0;i<50;i++){ui(()->ready[0]=iptv.player.engine.getPlaybackState()==androidx.media3.common.Player.STATE_READY);if(ready[0])break;Thread.sleep(500);}check(ready[0],"IPTV Media3 HLS playback prepares");ui(()->{check(iptv.player.engine.getCurrentTracks().getGroups().size()>0,"IPTV exposes stream tracks");iptv.player.showOptions();check(iptv.player.options.size()>=13,"Blades player options available");iptv.player.pause();check(!iptv.player.engine.getPlayWhenReady(),"IPTV pause works");iptv.player.close();check(iptv.player==null,"IPTV playback cleanup");});
   output.putString("stream","PASS: "+checks+" streaming checks");
  }catch(Throwable e){output.putString("stream","FAIL: "+e.getClass().getSimpleName()+": "+e.getMessage());}
  finally{ui(()->{if(browser!=null&&!browser.closed)browser.close();if(iptv!=null&&!iptv.closed)iptv.close(false);a.jellyfin.stopEncoding(session);try{JSONArray old=new JSONArray(a.iptv.prefs.getString("recent","[]")),clean=new JSONArray();for(int i=0;i<old.length();i++)if(!old.optString(i).equals("test-only-channel"))clean.put(old.optString(i));a.iptv.prefs.edit().putString("recent",clean.toString()).apply();}catch(Exception ignored){}});}
  finish(output.getString("stream").startsWith("PASS")?Activity.RESULT_OK:Activity.RESULT_CANCELED,output);
 }
}
